// Preconditions enforcement:
// - sprite must be a valid TFT_eSprite* provided by the fuzzer runtime.
// - The frame buffer may or may not be allocated; if the buffer was allocated by a prior
//   operation (e.g., createSprite), attribute "buffer_allocated" should be set to 1.
// - We must not dereference or free the returned buffer pointer.

// The uint8_t parameter is ignored by the API; any value is accepted.
uint8_t ignored = static_cast<uint8_t>(*FUZZ_PARAM(unsigned int) & 0xFF);

// Call the target function.
void *buf = sprite->frameBuffer(ignored);

// If we believe the buffer was allocated previously, it should not be null.
int was_alloc = FUZZ_GET_ATTR_INT(sprite, "buffer_allocated");
if (was_alloc) {
    FUZZ_ASSERT(buf != nullptr, "frameBuffer() returned nullptr despite prior allocation");
}

// If we observe a non-null buffer now, mark it as allocated for downstream stubs.
if (buf != nullptr) {
    FUZZ_SET_ATTR_INT(sprite, "buffer_allocated", 1);
}

