// Construct a TFT_eSprite instance. This class derives from LGFX_Sprite and can manage
// its own pixel buffer using createSprite().
TFT_eSprite *sprite = new TFT_eSprite();

// Optionally set a color depth before allocation to exercise different paths while
// controlling memory usage (< 2048 bytes per call).
// Choose among 8, 16, or 24 bits per pixel and then size the sprite so that
// width * height * bpp <= 2048.
unsigned int depth_sel = *FUZZ_PARAM(unsigned int);
int bpp;
switch (depth_sel % 3) {
  case 0: bpp = 1; sprite->setColorDepth(8);  break;  // 8bpp
  case 1: bpp = 2; sprite->setColorDepth(16); break;  // 16bpp
  default: bpp = 3; sprite->setColorDepth(24); break; // 24bpp
}

// Compute safe dimensions based on bpp. Keep area within 2048 bytes total.
// Ensure minimum dimension of 1.
size_t area_max = (size_t)2048 / (size_t)bpp;
if (area_max == 0) { area_max = 1; }

// Pick width within [1, min(64, area_max)]
size_t w_cap = area_max < 64 ? area_max : 64;
if (w_cap == 0) { w_cap = 1; }
unsigned int rw = *FUZZ_PARAM(unsigned int);
int w = (int)(rw % w_cap) + 1;

// Given width, pick height within [1, max(1, area_max / w)]
size_t h_cap = area_max / (size_t)w;
if (h_cap == 0) { h_cap = 1; }
unsigned int rh = *FUZZ_PARAM(unsigned int);
int h = (int)(rh % h_cap) + 1;

// With 50% probability, allocate a pixel buffer via createSprite().
// If allocation fails (nullptr), we retain the sprite without the buffer and
// do not set the allocation attribute.
bool do_alloc = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
if (do_alloc) {
  void *buf = sprite->createSprite(w, h);  // Owned by sprite; do not free.
  if (buf != nullptr) {
    FUZZ_SET_ATTR_INT(sprite, "buffer_allocated", 1);
    FUZZ_SET_ATTR_INT(sprite, "width", w);
    FUZZ_SET_ATTR_INT(sprite, "height", h);
    FUZZ_SET_ATTR_INT(sprite, "bpp", bpp);
  }
}

